{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "객실 400실 관광숙박시설의 중·대형 승합차 부설주차장 최소 설치 대수(서울특별시 주차장 설치 및 관리 조례 별표 기준)",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "객실 400실인 관광숙박시설은 서울특별시 주차장 설치 및 관리 조례 별표 4의 설치기준에 따라 중·대형 승합차 부설주차장을 최소 2대 이상 설치해야 한다. 별표 4는 관광숙박시설(건축법 시행령 별표1에 따른 관광숙박시설)의 설치기준을 ‘객실수 200실당 1대 이상’으로 정하고 있다. 400실은 200실당 1대 기준을 적용하면 2대에 해당하므로 최소 2대 이상이다.",
          "b_ids": "주차장:별표4#행2"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
